--[[\n    WeatherDashboard.lua\n    Creates a visual weather dashboard GUI in Roblox\n    Shows real-time weather for multiple cities\n]]\n\nlocal WeatherDashboard = {}\n\n-- Create a weather info label\nfunction WeatherDashboard:CreateWeatherLabel(parent, text, position)\n    local label = Instance.new(\"TextLabel\")\n    label.Name = \"WeatherLabel\"\n    label.Size = UDim2.new(0, 300, 0, 100)\n    label.Position = position\n    label.BackgroundColor3 = Color3.fromRGB(30, 30, 40)\n    label.TextColor3 = Color3.fromRGB(255, 255, 255)\n    label.TextSize = 14\n    label.Text = text\n    label.TextWrapped = true\n    label.BorderSizePixel = 0\n    label.Font = Enum.Font.GothamBold\n    label.Parent = parent\n    \n    -- Add a nice border\n    local corner = Instance.new(\"UICorner\")\n    corner.CornerRadius = UDim.new(0, 10)\n    corner.Parent = label\n    \n    return label\nend\n\n-- Create the main weather dashboard GUI\nfunction WeatherDashboard:CreateDashboard(player)\n    if not player:FindFirstChild(\"PlayerGui\") then\n        return nil\n    end\n    \n    local screenGui = Instance.new(\"ScreenGui\")\n    screenGui.Name = \"WeatherDashboard\"\n    screenGui.ResetOnSpawn = false\n    screenGui.Parent = player.PlayerGui\n    \n    -- Title\n    local title = Instance.new(\"TextLabel\")\n    title.Name = \"Title\"\n    title.Size = UDim2.new(0, 400, 0, 50)\n    title.Position = UDim2.new(0.5, -200, 0, 10)\n    title.BackgroundColor3 = Color3.fromRGB(0, 120, 215)\n    title.TextColor3 = Color3.fromRGB(255, 255, 255)\n    title.TextSize = 24\n    title.Text = \"🌍 WEATHER DASHBOARD\"\n    title.BorderSizePixel = 0\n    title.Font = Enum.Font.GothamBold\n    title.Parent = screenGui\n    \n    local titleCorner = Instance.new(\"UICorner\")\n    titleCorner.CornerRadius = UDim.new(0, 10)\n    titleCorner.Parent = title\n    \n    -- Weather info container\n    local container = Instance.new(\"Frame\")\n    container.Name = \"WeatherContainer\"\n    container.Size = UDim2.new(0, 400, 0, 350)\n    container.Position = UDim2.new(0.5, -200, 0, 70)\n    container.BackgroundColor3 = Color3.fromRGB(20, 20, 30)\n    container.BorderSizePixel = 0\n    container.Parent = screenGui\n    \n    local containerCorner = Instance.new(\"UICorner\")\n    containerCorner.CornerRadius = UDim.new(0, 10)\n    containerCorner.Parent = container\n    \n    -- Close button\n    local closeButton = Instance.new(\"TextButton\")\n    closeButton.Name = \"CloseButton\"\n    closeButton.Size = UDim2.new(0, 50, 0, 50)\n    closeButton.Position = UDim2.new(1, -60, 0, 10)\n    closeButton.BackgroundColor3 = Color3.fromRGB(211, 38, 38)\n    closeButton.TextColor3 = Color3.fromRGB(255, 255, 255)\n    closeButton.Text = \"X\"\n    closeButton.TextSize = 20\n    closeButton.Font = Enum.Font.GothamBold\n    closeButton.BorderSizePixel = 0\n    closeButton.Parent = screenGui\n    \n    local closeCorner = Instance.new(\"UICorner\")\n    closeCorner.CornerRadius = UDim.new(0, 5)\n    closeCorner.Parent = closeButton\n    \n    closeButton.MouseButton1Click:Connect(function()\n        screenGui:Destroy()\n    end)\n    \n    return screenGui, container\nend\n\n-- Update weather info in dashboard\nfunction WeatherDashboard:UpdateWeatherInfo(container, weatherText)\n    -- Clear existing labels\n    for _, child in pairs(container:GetChildren()) do\n        if child:IsA(\"TextLabel\") then\n            child:Destroy()\n        end\n    end\n    \n    -- Add weather info\n    self:CreateWeatherLabel(container, weatherText, UDim2.new(0, 10, 0, 10))\nend\n\nreturn WeatherDashboard